#!/usr/bin/env python3
"""Write the one package-version macro from Cargo.toml."""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import provenance

OUT = Path(__file__).resolve().parents[1] / "src" / "cargo_version.tex"


def main() -> int:
    version = provenance.library_version()
    OUT.write_text(
        "% Generated by paper/cpc/scripts/cargo_version_tex.py from Cargo.toml.\n"
        f"\\newcommand{{\\readconCargoVersion}}{{{version}}}\n",
        encoding="utf-8",
    )
    print(f"wrote paper/cpc/src/cargo_version.tex {version}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
